def early_deletion_days(tier, days_since_tier_change):
    minimum_days = {"Cool": 30, "Cold": 90, "Archive": 180}
    minimum = minimum_days.get(tier, 0)
    return max(0, minimum - days_since_tier_change)

blobs = [
    ("informes-2025.csv", "Cool", 21),
    ("respaldo-marzo.zip", "Archive", 45),
    ("catalogo-productos.json", "Cold", 90),
]

for name, tier, days in blobs:
    penalty_days = early_deletion_days(tier, days)
    print(f"{name} ({tier}, {days} dias en el nivel): dias facturados por eliminacion anticipada = {penalty_days}")
